import React from "react";
import { useNavigate, useParams } from "react-router-dom";

function prettify(slug = "") {
  return slug
    .split("-")
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join(" ");
}

export default function SlugStub({ prefix = "Page" }) {
  const { slug } = useParams();
  const nav = useNavigate();
  const title = `${prefix}: ${prettify(slug)}`;

  return (
    <div className="min-h-screen bg-gray-800 text-white pt-20">
      <section className="w-full px-3 md:px-6 py-10">
        <h1 className="text-3xl md:text-4xl font-extrabold">{title}</h1>
        <p className="mt-3 text-white/80 max-w-3xl">
          Stub route for <code className="bg-white/10 px-1.5 py-0.5 rounded">{slug}</code>. Replace with your real page when ready.
        </p>

        <div className="mt-8 flex gap-3 flex-wrap">
          <button
            onClick={() => nav("/mock-interview")}
            className="bg-green-500 hover:bg-green-400 text-gray-900 px-5 py-2.5 rounded-lg font-semibold"
          >
            Start Interview
          </button>
          <button
            onClick={() => nav("/")}
            className="border border-white/25 hover:bg-white/10 px-5 py-2.5 rounded-lg font-semibold"
          >
            Back to Home
          </button>
        </div>
      </section>
    </div>
  );
}
